@pytest.mark.parametrize("case", GRAPH_CASES, ids=[c["id"] for c in GRAPH_CASES])
def test_project_diagnostics_over_import_graphs(run, workdir, case):
    """CATCHES: errors reported for the wrong modules, in a different module order or under a
    different header, a cross-module error attributed to the wrong side, a wrong total,
    or a clean graph compiled/run/emitted differently."""
    S.check(run, workdir, case, __file__)
